/**
 * Deterministic test-harness generation.
 *
 * The old pipeline asked the model to write `Main` *and* `Solution`, then believed the
 * `ALL_TESTS_PASSED` string that same model chose to print (audit finding C2). Here the
 * harness is generated by code from LeetCode's own example inputs and the `Output:` values
 * in the statement, and the solution under test is injected verbatim. The model never
 * writes an assertion and never gets to replace the code being tested.
 *
 * When a type or an expected value cannot be handled, the case is reported as
 * unsupported rather than guessed — an invented oracle is worse than no oracle.
 */

import type { JavaContract, JavaMethodContract, Problem } from '../types.ts';

export type HarnessCase = {
  index: number;
  /** The official input, as given by LeetCode. */
  input: string;
  /** Canonical expected value, or undefined when we could not derive one. */
  expected?: string;
  supported: boolean;
  reason?: string;
};

export type HarnessBuild =
  | {
      supported: true;
      source: string;
      cases: HarnessCase[];
      /** Number of cases with a trustworthy expected value. */
      verifiableCases: number;
      /** Extra no-oracle checks included in this harness. */
      extraChecks: string[];
      notes: string[];
    }
  | { supported: false; reason: string; cases: HarnessCase[]; notes: string[] };

/* ------------------------------------------------------------------ *
 * Canonical value formatting (must match the Java serializer below)   *
 * ------------------------------------------------------------------ */

/** Rounds like the Java side so `6.00000`, `6.0` and `6` all canonicalise to `6`. */
function canonicalNumber(value: number): string {
  if (!Number.isFinite(value)) return String(value);
  if (Number.isInteger(value)) return String(value);
  const rounded = Math.round(value * 1e5) / 1e5;
  return String(rounded);
}

export function canonicalJson(value: unknown): string {
  if (value === null || value === undefined) return 'null';
  if (typeof value === 'number') return canonicalNumber(value);
  if (typeof value === 'boolean') return value ? 'true' : 'false';
  if (typeof value === 'string') return JSON.stringify(value);
  if (Array.isArray(value)) return `[${value.map(canonicalJson).join(',')}]`;
  return JSON.stringify(value);
}

/** Parses a LeetCode example value. LeetCode writes JSON, but not every statement does. */
function parseValue(raw: string): { ok: true; value: unknown } | { ok: false; reason: string } {
  const text = raw.trim();
  if (!text) return { ok: false, reason: 'empty value' };
  try {
    return { ok: true, value: JSON.parse(text) };
  } catch {
    // Single-quoted characters appear in a few statements: 'a' -> "a".
    if (/^'(\\.|[^'])'$/.test(text)) {
      try {
        return { ok: true, value: JSON.parse(`"${text.slice(1, -1)}"`) };
      } catch {
        /* fall through */
      }
    }
    return { ok: false, reason: `not a JSON value: ${text.slice(0, 60)}` };
  }
}

/* ------------------------------------------------------------------ *
 * JSON value -> Java expression, driven by the declared parameter type *
 * ------------------------------------------------------------------ */

const PRIMITIVE_ARRAY_TYPES = new Set(['int[]', 'long[]', 'double[]', 'boolean[]', 'char[]', 'String[]']);

function javaString(value: string): string {
  return JSON.stringify(value);
}

class UnsupportedType extends Error {}

function literal(type: string, value: unknown): string {
  switch (type) {
    case 'int':
      assertNumber(value, type);
      return String(value);
    case 'long':
      assertNumber(value, type);
      return `${value}L`;
    case 'double':
    case 'float':
      assertNumber(value, type);
      return `${value}`;
    case 'boolean':
      if (typeof value !== 'boolean') throw new UnsupportedType(`expected a boolean for ${type}`);
      return value ? 'true' : 'false';
    case 'char': {
      if (typeof value !== 'string' || [...value].length !== 1) {
        throw new UnsupportedType(`expected a single character for ${type}`);
      }
      return `'${value === "'" ? "\\'" : value === '\\' ? '\\\\' : value}'`;
    }
    case 'String':
      if (value === null) return 'null';
      if (typeof value !== 'string') throw new UnsupportedType('expected a string');
      return javaString(value);
    case 'Integer':
      return value === null ? 'null' : `Integer.valueOf(${String(value)})`;
    case 'List<Integer>':
    case 'List<Long>':
    case 'List<Double>':
    case 'List<String>':
    case 'List<Boolean>':
    case 'List<Character>': {
      const inner = type.slice('List<'.length, -1);
      return `__list(${arrayLiteral(boxed(inner), value)})`;
    }
    case 'List<List<Integer>>':
    case 'List<List<String>>':
    case 'List<List<Character>>': {
      const inner = type.slice('List<'.length, -1); // List<Integer>
      if (!Array.isArray(value)) throw new UnsupportedType(`expected an array for ${type}`);
      return `__listOfLists(new java.util.List[]{${value.map((row) => literal(inner, row)).join(', ')}})`;
    }
    default:
      break;
  }

  if (PRIMITIVE_ARRAY_TYPES.has(type)) {
    const element = type.slice(0, -2);
    return `new ${element}[]{${arrayElements(element, value)}}`;
  }

  // Two-dimensional primitive arrays.
  const matrix = /^(int|long|double|boolean|char|String)\[\]\[\]$/.exec(type);
  if (matrix) {
    const element = matrix[1];
    if (!Array.isArray(value)) throw new UnsupportedType(`expected a 2-D array for ${type}`);
    return `new ${element}[][]{${value
      .map((row) => `{${arrayElements(element, row)}}`)
      .join(', ')}}`;
  }

  if (type === 'ListNode') return `__toListNode(${nullableIntArray(value)})`;
  if (type === 'TreeNode') return `__toTree(${nullableIntArray(value)})`;
  if (type === 'ListNode[]') {
    if (!Array.isArray(value)) throw new UnsupportedType('expected an array of lists');
    return `new ListNode[]{${value.map((row) => `__toListNode(${nullableIntArray(row)})`).join(', ')}}`;
  }

  throw new UnsupportedType(`parameter type ${type} is not supported by the deterministic harness`);
}

function assertNumber(value: unknown, type: string): void {
  if (typeof value !== 'number') throw new UnsupportedType(`expected a number for ${type}`);
}

function boxed(inner: string): string {
  return inner;
}

function arrayElements(element: string, value: unknown): string {
  if (!Array.isArray(value)) throw new UnsupportedType(`expected an array of ${element}`);
  return value.map((item) => literal(element, item)).join(', ');
}

function arrayLiteral(boxType: string, value: unknown): string {
  if (!Array.isArray(value)) throw new UnsupportedType(`expected an array for List<${boxType}>`);
  const java = boxType === 'Character' ? 'Character' : boxType;
  const items = value.map((item) => {
    if (boxType === 'Character') return literal('char', item);
    if (boxType === 'String') return literal('String', item);
    if (boxType === 'Boolean') return literal('boolean', item);
    if (boxType === 'Long') return literal('long', item);
    if (boxType === 'Double') return literal('double', item);
    return literal('int', item);
  });
  return `new ${java}[]{${items.join(', ')}}`;
}

function nullableIntArray(value: unknown): string {
  if (!Array.isArray(value)) throw new UnsupportedType('expected an array of integers (or nulls)');
  const items = value.map((item) => {
    if (item === null) return 'null';
    if (typeof item !== 'number') throw new UnsupportedType('expected integers or nulls');
    return String(item);
  });
  return `new Integer[]{${items.join(', ')}}`;
}

/* ------------------------------------------------------------------ *
 * Java support code                                                   *
 * ------------------------------------------------------------------ */

const LIST_NODE_DEF = `class ListNode {
    int val;
    ListNode next;
    ListNode() {}
    ListNode(int val) { this.val = val; }
    ListNode(int val, ListNode next) { this.val = val; this.next = next; }
}`;

const TREE_NODE_DEF = `class TreeNode {
    int val;
    TreeNode left;
    TreeNode right;
    TreeNode() {}
    TreeNode(int val) { this.val = val; }
    TreeNode(int val, TreeNode left, TreeNode right) { this.val = val; this.left = left; this.right = right; }
}`;

function supportCode(helpers: { listNode: boolean; treeNode: boolean }): string {
  const parts: string[] = [];

  parts.push(`    static String __num(double v) {
        if (v == Math.rint(v) && !Double.isInfinite(v) && Math.abs(v) < 1e15) {
            return String.valueOf((long) v);
        }
        double r = Math.round(v * 1e5) / 1e5;
        String s = String.valueOf(r);
        if (s.endsWith(".0")) s = s.substring(0, s.length() - 2);
        return s;
    }

    static String __str(String v) {
        StringBuilder sb = new StringBuilder("\\"");
        for (int i = 0; i < v.length(); i++) {
            char c = v.charAt(i);
            if (c == '"' || c == '\\\\') sb.append('\\\\').append(c);
            else if (c == '\\n') sb.append("\\\\n");
            else if (c == '\\r') sb.append("\\\\r");
            else if (c == '\\t') sb.append("\\\\t");
            else sb.append(c);
        }
        return sb.append('"').toString();
    }

    @SuppressWarnings("unchecked")
    static String __ser(Object v) {
        if (v == null) return "null";
        if (v instanceof String) return __str((String) v);
        if (v instanceof Character) return __str(String.valueOf(v));
        if (v instanceof Boolean) return v.toString();
        if (v instanceof Double || v instanceof Float) return __num(((Number) v).doubleValue());
        if (v instanceof Number) return v.toString();
        if (v instanceof int[]) { StringBuilder sb = new StringBuilder("["); int[] a = (int[]) v; for (int i = 0; i < a.length; i++) { if (i > 0) sb.append(','); sb.append(a[i]); } return sb.append(']').toString(); }
        if (v instanceof long[]) { StringBuilder sb = new StringBuilder("["); long[] a = (long[]) v; for (int i = 0; i < a.length; i++) { if (i > 0) sb.append(','); sb.append(a[i]); } return sb.append(']').toString(); }
        if (v instanceof double[]) { StringBuilder sb = new StringBuilder("["); double[] a = (double[]) v; for (int i = 0; i < a.length; i++) { if (i > 0) sb.append(','); sb.append(__num(a[i])); } return sb.append(']').toString(); }
        if (v instanceof boolean[]) { StringBuilder sb = new StringBuilder("["); boolean[] a = (boolean[]) v; for (int i = 0; i < a.length; i++) { if (i > 0) sb.append(','); sb.append(a[i]); } return sb.append(']').toString(); }
        if (v instanceof char[]) { StringBuilder sb = new StringBuilder("["); char[] a = (char[]) v; for (int i = 0; i < a.length; i++) { if (i > 0) sb.append(','); sb.append(__str(String.valueOf(a[i]))); } return sb.append(']').toString(); }
        if (v instanceof Object[]) { StringBuilder sb = new StringBuilder("["); Object[] a = (Object[]) v; for (int i = 0; i < a.length; i++) { if (i > 0) sb.append(','); sb.append(__ser(a[i])); } return sb.append(']').toString(); }
        if (v instanceof java.util.Collection) { StringBuilder sb = new StringBuilder("["); boolean first = true; for (Object o : (java.util.Collection<Object>) v) { if (!first) sb.append(','); first = false; sb.append(__ser(o)); } return sb.append(']').toString(); }`);

  if (helpers.listNode) {
    parts.push(`        if (v instanceof ListNode) { StringBuilder sb = new StringBuilder("["); ListNode n = (ListNode) v; boolean first = true; int guard = 0; while (n != null && guard++ < 100000) { if (!first) sb.append(','); first = false; sb.append(n.val); n = n.next; } return sb.append(']').toString(); }`);
  }
  if (helpers.treeNode) {
    parts.push(`        if (v instanceof TreeNode) {
            java.util.List<String> out = new java.util.ArrayList<>();
            java.util.Deque<TreeNode> queue = new java.util.ArrayDeque<>();
            TreeNode root = (TreeNode) v;
            queue.add(root);
            while (!queue.isEmpty()) {
                TreeNode node = queue.poll();
                if (node == null) { out.add("null"); continue; }
                out.add(String.valueOf(node.val));
                queue.add(node.left);
                queue.add(node.right);
            }
            int end = out.size();
            while (end > 0 && out.get(end - 1).equals("null")) end--;
            return "[" + String.join(",", out.subList(0, end)) + "]";
        }`);
  }

  parts.push(`        return __str(String.valueOf(v));
    }

    static <T> java.util.List<T> __list(T[] items) {
        return new java.util.ArrayList<>(java.util.Arrays.asList(items));
    }

    @SuppressWarnings({"unchecked", "rawtypes"})
    static <T> java.util.List<java.util.List<T>> __listOfLists(java.util.List[] rows) {
        java.util.List<java.util.List<T>> out = new java.util.ArrayList<>();
        for (java.util.List row : rows) out.add((java.util.List<T>) row);
        return out;
    }`);

  if (helpers.listNode) {
    parts.push(`
    static String __serNode(ListNode v) { return v == null ? "[]" : __ser(v); }

    static ListNode __toListNode(Integer[] values) {
        ListNode dummy = new ListNode();
        ListNode tail = dummy;
        for (Integer value : values) {
            if (value == null) continue;
            tail.next = new ListNode(value);
            tail = tail.next;
        }
        return dummy.next;
    }`);
  }
  if (helpers.treeNode) {
    parts.push(`
    static String __serNode(TreeNode v) { return v == null ? "[]" : __ser(v); }

    static TreeNode __toTree(Integer[] values) {
        if (values.length == 0 || values[0] == null) return null;
        TreeNode root = new TreeNode(values[0]);
        java.util.Deque<TreeNode> queue = new java.util.ArrayDeque<>();
        queue.add(root);
        int i = 1;
        while (!queue.isEmpty() && i < values.length) {
            TreeNode node = queue.poll();
            if (i < values.length) {
                Integer left = values[i++];
                if (left != null) { node.left = new TreeNode(left); queue.add(node.left); }
            }
            if (i < values.length) {
                Integer right = values[i++];
                if (right != null) { node.right = new TreeNode(right); queue.add(node.right); }
            }
        }
        return root;
    }`);
  }

  return parts.join('\n');
}

/* ------------------------------------------------------------------ *
 * Harness assembly                                                    *
 * ------------------------------------------------------------------ */

/** Moves `import` statements out of a solution so they can be emitted at file top. */
export function hoistImports(code: string): { imports: string[]; body: string } {
  const imports: string[] = [];
  const body: string[] = [];

  for (const line of code.trim().split('\n')) {
    const match = /^\s*(import\s+(?:static\s+)?[\w.*]+\s*;)\s*$/.exec(line);
    if (match) {
      // Skipping the wildcard imports already emitted keeps the file tidy.
      if (!['import java.util.*;', 'import java.math.*;'].includes(match[1].replace(/\s+/g, ' '))) {
        imports.push(match[1]);
      }
      continue;
    }
    body.push(line);
  }

  return { imports: [...new Set(imports)], body: body.join('\n').trim() };
}

/** Node return types need a type-aware serializer: a null list/tree prints as `[]`. */
function serializerCall(returnType: string, expression: string): string {
  if (returnType === 'ListNode' || returnType === 'TreeNode') return `__serNode(${expression})`;
  return `__ser(${expression})`;
}

type BuildOptions = {
  /** Include the no-oracle stability checks (skipped for design problems). */
  extraChecks?: boolean;
};

export function buildHarness(
  problem: Problem,
  contract: JavaContract,
  solutionCode: string,
  options: BuildOptions = {},
): HarnessBuild {
  const notes: string[] = [];

  if (problem.exampleTestcases.length === 0) {
    return { supported: false, reason: 'LeetCode returned no official example test cases.', cases: [], notes };
  }

  const helpers = {
    listNode: contract.requiredHelpers.includes('ListNode'),
    treeNode: contract.requiredHelpers.includes('TreeNode'),
  };

  const unknownHelpers = contract.requiredHelpers.filter((h) => h !== 'ListNode' && h !== 'TreeNode');
  if (unknownHelpers.length > 0) {
    return {
      supported: false,
      reason: `Problem uses helper type(s) the deterministic harness does not model: ${unknownHelpers.join(', ')}.`,
      cases: [],
      notes,
    };
  }

  const build =
    contract.kind === 'design'
      ? buildDesignBody(problem, contract, notes)
      : buildAlgorithmBody(problem, contract, notes, options.extraChecks ?? true);

  if (!build.ok) {
    return { supported: false, reason: build.reason, cases: build.cases, notes };
  }

  // LeetCode's Java environment has these in scope implicitly, so generated solutions
  // routinely use List/Map/Deque with no import. Without them a correct solution fails to
  // compile here for a reason that would never occur on LeetCode. Any imports the solution
  // brought along are hoisted, because Java requires every import before the first type.
  const { imports, body: solutionBody } = hoistImports(solutionCode);
  const importBlock = [
    'import java.util.*;',
    'import java.util.function.*;',
    'import java.util.stream.*;',
    'import java.math.*;',
    ...imports,
  ].join('\n');

  const source = `${importBlock}

${helpers.listNode ? `${LIST_NODE_DEF}\n\n` : ''}${helpers.treeNode ? `${TREE_NODE_DEF}\n\n` : ''}${solutionBody}

public class Main {
${supportCode(helpers)}

    static int __passed = 0;
    static int __total = 0;

    static void __check(String label, String expected, String actual) {
        __total++;
        boolean ok = expected.equals(actual);
        if (ok) { __passed++; System.out.println("CASE " + label + " PASS"); }
        else System.out.println("CASE " + label + " FAIL expected=" + expected + " actual=" + actual);
    }

    public static void main(String[] args) {
        try {
${build.body}
        } catch (Throwable t) {
            System.out.println("HARNESS_EXCEPTION " + t.getClass().getName() + ": " + t.getMessage());
            StackTraceElement[] trace = t.getStackTrace();
            for (int i = 0; i < Math.min(5, trace.length); i++) System.out.println("    at " + trace[i]);
            System.out.println("RESULT FAILED " + __passed + "/" + __total);
            return;
        }
        System.out.println("RESULT " + (__passed == __total && __total > 0 ? "PASSED " : "FAILED ") + __passed + "/" + __total);
    }
}
`;

  return {
    supported: true,
    source,
    cases: build.cases,
    verifiableCases: build.cases.filter((c) => c.supported).length,
    extraChecks: build.extraChecks,
    notes,
  };
}

/**
 * A harness that only proves the solution compiles against the required interface.
 *
 * Used when example cases cannot be turned into deterministic checks: "it compiles" is a
 * real, honest rung on the ladder, and it is strictly better than reporting nothing.
 */
export function buildCompileOnlyHarness(contract: JavaContract, solutionCode: string): string {
  const helpers = {
    listNode: contract.requiredHelpers.includes('ListNode'),
    treeNode: contract.requiredHelpers.includes('TreeNode'),
  };
  const { imports, body } = hoistImports(solutionCode);

  return `${['import java.util.*;', 'import java.util.function.*;', 'import java.util.stream.*;', 'import java.math.*;', ...imports].join('\n')}

${helpers.listNode ? `${LIST_NODE_DEF}\n\n` : ''}${helpers.treeNode ? `${TREE_NODE_DEF}\n\n` : ''}${body}

public class Main {
    public static void main(String[] args) {
        Class<?> required = ${contract.className}.class;
        System.out.println("CASE compile-only(" + required.getSimpleName() + ") PASS");
        System.out.println("RESULT PASSED 1/1");
    }
}
`;
}

type BodyBuild =
  | { ok: true; body: string; cases: HarnessCase[]; extraChecks: string[] }
  | { ok: false; reason: string; cases: HarnessCase[] };

function primaryMethod(contract: JavaContract): JavaMethodContract | undefined {
  return contract.methods.find((m) => !m.isConstructor);
}

function buildAlgorithmBody(
  problem: Problem,
  contract: JavaContract,
  notes: string[],
  extraChecks: boolean,
): BodyBuild {
  const method = primaryMethod(contract);
  if (!method) return { ok: false, reason: 'The contract declares no method to call.', cases: [] };

  const cases: HarnessCase[] = [];
  const statements: string[] = [];
  const replay: string[] = [];
  const isVoid = method.returnType === 'void';

  // For a void method, LeetCode's "Output" is the mutated argument. Only a single
  // mutable argument can be checked unambiguously.
  const mutableParamIndex = isVoid ? method.paramTypes.findIndex((t) => t.endsWith('[]') || t.startsWith('List<')) : -1;
  if (isVoid && mutableParamIndex < 0) {
    return {
      ok: false,
      reason: `Method ${method.name} returns void and no mutable argument could be identified, so there is nothing to verify deterministically.`,
      cases: [],
    };
  }

  for (let i = 0; i < problem.exampleTestcases.length; i++) {
    const raw = problem.exampleTestcases[i];
    const lines = raw.split('\n');
    const expectedRaw = problem.exampleOutputs[i];

    if (lines.length !== method.paramTypes.length) {
      cases.push({
        index: i,
        input: raw,
        supported: false,
        reason: `case has ${lines.length} argument(s) but the contract takes ${method.paramTypes.length}`,
      });
      continue;
    }

    if (expectedRaw === undefined) {
      cases.push({ index: i, input: raw, supported: false, reason: 'no matching Output: value in the statement' });
      continue;
    }

    const expectedParsed = parseValue(expectedRaw);
    if (!expectedParsed.ok) {
      cases.push({ index: i, input: raw, supported: false, reason: `expected value ${expectedParsed.reason}` });
      continue;
    }

    let args: string[];
    try {
      args = lines.map((line, index) => {
        const parsed = parseValue(line);
        if (!parsed.ok) throw new UnsupportedType(`argument ${index + 1} ${parsed.reason}`);
        return literal(method.paramTypes[index], parsed.value);
      });
    } catch (error) {
      cases.push({
        index: i,
        input: raw,
        supported: false,
        reason: error instanceof Error ? error.message : String(error),
      });
      continue;
    }

    const expected = canonicalJson(expectedParsed.value);
    cases.push({ index: i, input: raw, expected, supported: true });

    const argVars = args.map((arg, index) => `            ${method.paramTypes[index]} a${i}_${index} = ${arg};`);
    const callArgs = args.map((_, index) => `a${i}_${index}`).join(', ');

    if (isVoid) {
      statements.push(
        ...argVars,
        `            new ${contract.className}().${method.name}(${callArgs});`,
        `            __check("${i + 1}", ${javaString(expected)}, __ser(a${i}_${mutableParamIndex}));`,
      );
    } else {
      statements.push(
        ...argVars,
        `            __check("${i + 1}", ${javaString(expected)}, ${serializerCall(
          method.returnType,
          `new ${contract.className}().${method.name}(${callArgs})`,
        )});`,
      );
    }

    if (extraChecks && !isVoid) {
      // Same instance reused across cases: catches state leaking between judge calls.
      replay.push(
        ...args.map((arg, index) => `            ${method.paramTypes[index]} r${i}_${index} = ${arg};`),
        `            __check("${i + 1}-shared-instance", ${javaString(expected)}, ${serializerCall(
          method.returnType,
          `__shared.${method.name}(${args.map((_, index) => `r${i}_${index}`).join(', ')})`,
        )});`,
      );
    }
  }

  const supported = cases.filter((c) => c.supported);
  if (supported.length === 0) {
    return {
      ok: false,
      reason: `None of the ${cases.length} official example case(s) could be turned into a deterministic check: ${
        cases.map((c) => c.reason).filter(Boolean).join('; ') || 'unknown reason'
      }`,
      cases,
    };
  }

  if (supported.length < cases.length) {
    notes.push(
      `${cases.length - supported.length} of ${cases.length} official example case(s) could not be checked deterministically and were skipped rather than guessed.`,
    );
  }

  const extras: string[] = [];
  const body = [...statements];

  if (replay.length > 0) {
    extras.push('shared-instance replay (detects state leaking between test cases)');
    body.push(
      '',
      `            ${contract.className} __shared = new ${contract.className}();`,
      ...replay,
    );
  }

  return { ok: true, body: body.join('\n'), cases, extraChecks: extras };
}

function buildDesignBody(problem: Problem, contract: JavaContract, notes: string[]): BodyBuild {
  const constructor = contract.methods.find((m) => m.isConstructor);
  const cases: HarnessCase[] = [];
  const body: string[] = [];
  let built = 0;

  for (let i = 0; i < problem.exampleTestcases.length; i++) {
    const raw = problem.exampleTestcases[i];
    const lines = raw.split('\n');
    const expectedRaw = problem.exampleOutputs[i];

    if (lines.length < 2) {
      cases.push({ index: i, input: raw, supported: false, reason: 'design case needs an operations array and an arguments array' });
      continue;
    }

    const ops = parseValue(lines[0]);
    const argSets = parseValue(lines[1]);
    const expectedParsed = expectedRaw
      ? parseValue(expectedRaw)
      : ({ ok: false, reason: 'no Output: value' } as const);

    if (!ops.ok) {
      cases.push({ index: i, input: raw, supported: false, reason: ops.reason });
      continue;
    }
    if (!argSets.ok) {
      cases.push({ index: i, input: raw, supported: false, reason: argSets.reason });
      continue;
    }
    if (!expectedParsed.ok) {
      cases.push({ index: i, input: raw, supported: false, reason: expectedParsed.reason });
      continue;
    }

    if (!Array.isArray(ops.value) || !Array.isArray(argSets.value) || !Array.isArray(expectedParsed.value)) {
      cases.push({ index: i, input: raw, supported: false, reason: 'design case arrays are malformed' });
      continue;
    }

    const operations = ops.value as string[];
    const argLists = argSets.value as unknown[][];
    const expectedValues = expectedParsed.value as unknown[];

    if (operations.length !== argLists.length || operations.length !== expectedValues.length) {
      cases.push({ index: i, input: raw, supported: false, reason: 'operations, arguments and expected outputs have different lengths' });
      continue;
    }

    const statements: string[] = [];
    let failedReason: string | undefined;
    const instance = `obj${i}`;

    for (let step = 0; step < operations.length; step++) {
      const op = operations[step];
      const stepArgs = argLists[step] ?? [];

      try {
        if (step === 0) {
          if (op !== contract.className) {
            throw new UnsupportedType(`first operation "${op}" is not the constructor "${contract.className}"`);
          }
          const paramTypes = constructor?.paramTypes ?? [];
          if (paramTypes.length !== stepArgs.length) {
            throw new UnsupportedType(`constructor expects ${paramTypes.length} argument(s), case provides ${stepArgs.length}`);
          }
          const args = stepArgs.map((value, index) => literal(paramTypes[index], value));
          statements.push(`            ${contract.className} ${instance} = new ${contract.className}(${args.join(', ')});`);
          continue;
        }

        const method = contract.methods.find((m) => !m.isConstructor && m.name === op && m.paramTypes.length === stepArgs.length);
        if (!method) throw new UnsupportedType(`operation "${op}" with ${stepArgs.length} argument(s) is not in the official contract`);

        const args = stepArgs.map((value, index) => literal(method.paramTypes[index], value));
        const expected = canonicalJson(expectedValues[step]);
        const label = `${i + 1}.${step + 1} ${op}`;

        if (method.returnType === 'void') {
          statements.push(`            ${instance}.${op}(${args.join(', ')});`);
          // LeetCode records `null` for a void operation; verify the expectation agrees.
          if (expected !== 'null') {
            throw new UnsupportedType(`operation "${op}" returns void but the statement expects ${expected}`);
          }
        } else {
          statements.push(
            `            __check("${label}", ${javaString(expected)}, ${serializerCall(
              method.returnType,
              `${instance}.${op}(${args.join(', ')})`,
            )});`,
          );
        }
      } catch (error) {
        failedReason = error instanceof Error ? error.message : String(error);
        break;
      }
    }

    if (failedReason) {
      cases.push({ index: i, input: raw, supported: false, reason: failedReason });
      continue;
    }

    cases.push({ index: i, input: raw, expected: canonicalJson(expectedValues), supported: true });
    body.push(...statements);
    built++;
  }

  if (built === 0) {
    return {
      ok: false,
      reason: `No design-problem operation sequence could be built deterministically: ${
        cases.map((c) => c.reason).filter(Boolean).join('; ') || 'unknown reason'
      }`,
      cases,
    };
  }

  if (built < cases.length) {
    notes.push(`${cases.length - built} design case(s) were skipped rather than guessed.`);
  }

  return { ok: true, body: body.join('\n'), cases, extraChecks: [] };
}

/* ------------------------------------------------------------------ *
 * Output parsing                                                      *
 * ------------------------------------------------------------------ */

export type HarnessReport = {
  ran: boolean;
  passed: boolean;
  total: number;
  passedCount: number;
  cases: { index: number; passed: boolean; expected?: string; actual?: string; label?: string }[];
  exception?: string;
};

/** Parses the machine-readable protocol the generated harness prints. */
export function parseHarnessOutput(stdout: string): HarnessReport {
  const cases: HarnessReport['cases'] = [];
  let passedCount = 0;
  let total = 0;
  let ran = false;
  let passed = false;
  let exception: string | undefined;

  for (const line of stdout.split('\n')) {
    const text = line.trim();

    const caseMatch = /^CASE\s+(\S+)\s+(PASS|FAIL)(?:\s+expected=(.*?)\s+actual=(.*))?$/.exec(text);
    if (caseMatch) {
      const [, label, verdict, expected, actual] = caseMatch;
      cases.push({
        index: cases.length,
        label,
        passed: verdict === 'PASS',
        expected,
        actual,
      });
      continue;
    }

    const resultMatch = /^RESULT\s+(PASSED|FAILED)\s+(\d+)\/(\d+)$/.exec(text);
    if (resultMatch) {
      ran = true;
      passed = resultMatch[1] === 'PASSED';
      passedCount = Number(resultMatch[2]);
      total = Number(resultMatch[3]);
      continue;
    }

    if (text.startsWith('HARNESS_EXCEPTION')) {
      exception = text.slice('HARNESS_EXCEPTION'.length).trim();
    }
  }

  return { ran, passed: passed && total > 0, total, passedCount, cases, exception };
}
